<script setup>
import {ref,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {X,RefreshCw,CheckCircle2,AlertCircle,Users,SearchCheck} from 'lucide-vue-next'
import {voiceApi as api,stamp} from '../voice/operations'
const props=defineProps({queue:{type:Object,required:true}}),emit=defineEmits(['close'])
const data=ref(null),error=ref(''),loading=ref(false),dialog=ref(null)
let disposed=false,returnFocus
const summary={blocked:'Há impedimentos na operação',attention:'Há pontos para conferir',checks_passed:'Nenhum impedimento nas verificações feitas'}
async function load(){if(loading.value)return;loading.value=true;error.value='';try{const d=await api('/supervision/queues/'+props.queue.id+'/diagnostic');if(!disposed)data.value=d}catch(e){if(!disposed)error.value=e.message}finally{loading.value=false}}
function keys(e){if(e.key!=='Tab')return;const items=[...dialog.value.querySelectorAll('button:not(:disabled),a[href],summary')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
onMounted(async()=>{returnFocus=document.activeElement;await nextTick();dialog.value?.querySelector('button')?.focus();load()})
onBeforeUnmount(()=>{disposed=true;returnFocus?.focus()})
</script>
<template>
<Teleport to="body"><div class="qd-overlay"><section ref="dialog" class="qd-dialog" role="dialog" aria-modal="true" aria-labelledby="qd-title" @keydown="keys">
<button class="secondary qd-close" aria-label="Fechar diagnóstico" @click="emit('close')"><X :size="18"/></button>
<span class="qd-kicker">ENTENDA A OPERAÇÃO</span><h2 id="qd-title">Diagnóstico da fila</h2><p class="qd-name">{{queue.name}}</p>
<p v-if="error" role="alert" class="qd-error">{{error}} <span v-if="data">Os dados abaixo são da última consulta.</span></p>
<div class="qd-toolbar"><small>{{data?'Consulta de '+stamp(data.generated_at):'Verificação dos registros atuais'}}</small><button class="secondary" :disabled="loading" @click="load"><RefreshCw :size="14"/>{{loading?'Consultando…':'Atualizar diagnóstico'}}</button></div>
<p v-if="loading&&!data" role="status">Conferindo operação, equipe e público…</p>
<template v-if="data"><div class="qd-summary" :class="data.status"><SearchCheck :size="23"/><div><strong>{{summary[data.status]}}</strong><small>Esta consulta não habilita filas nem inicia chamadas.</small></div></div>
<div class="qd-checks"><article v-for="c in data.checks" :key="c.code" :class="c.status"><CheckCircle2 v-if="c.status==='ok'" :size="18"/><AlertCircle v-else :size="18"/><div><strong>{{c.title}}</strong><p v-if="c.status!=='ok'">{{c.action}}</p></div></article></div>
<details class="qd-section"><summary><Users :size="17"/> Equipe · {{data.agents.counts.available}} disponível(is)</summary><p v-if="data.agents.partial" class="qd-note">Exibindo até 200 atendentes; os totais desta seção são parciais.</p><ul class="qd-agents"><li v-for="a in data.agents.data" :key="a.id"><strong>{{a.name}}</strong><span>{{a.detail}}<template v-if="data.queue.direction!=='outbound'"> · {{a.inbound_ready?'Áudio receptivo pronto':'Áudio receptivo não confirmado'}}</template></span></li></ul><p v-if="!data.agents.data.length">Nenhum atendente vinculado a esta fila.</p></details>
<section v-if="data.queue.direction!=='inbound'" class="qd-section"><h3>Público das cadências</h3><div class="qd-metrics"><div><strong>{{data.audience.evaluated}}</strong><small>participações avaliadas</small></div><div><strong>{{data.audience.eligible}}</strong><small>sem impedimento na amostra</small></div><div><strong>{{data.audience.blocked}}</strong><small>com impedimento</small></div></div>
<p class="qd-note">{{data.audience.partial?'Amostra parcial: '+data.audience.evaluated+' de '+data.audience.total+' participações registradas.':'Foram consultadas as '+data.audience.total+' participações registradas.'}} Uma pessoa em duas cadências conta duas vezes. A amostra segue a ordem das cadências e dos contatos; não é uma previsão da ordem de discagem.</p>
<details v-for="r in data.audience.reasons" :key="r.reason" class="qd-reason"><summary><span>{{r.reason}}</span><b>{{r.count}}</b></summary><p class="qd-note">Exemplos deste motivo · até três participações</p><ul><li v-for="(e,i) in r.examples" :key="i"><strong>{{e.name}}</strong><span>{{e.phone}} · {{e.campaign}}</span></li></ul></details>
<p v-if="!data.audience.total">Vincule uma cadência e confira seu segmento para disponibilizar o público.</p></section>
<p class="qd-scope">{{data.scope}}</p></template>
</section></div></Teleport>
</template>
<style>
.qd-overlay{position:fixed;inset:0;z-index:1250;background:#19241d55;backdrop-filter:blur(3px);display:grid;place-items:center;padding:20px}.qd-dialog{position:relative;width:min(780px,100%);max-height:90dvh;overflow:auto;border-radius:24px;padding:30px;background:#fff;color:#293b31;box-shadow:0 30px 90px #17261d33}.qd-close{position:absolute;right:18px;top:18px;display:flex;padding:8px!important}.qd-kicker{font-size:10px;letter-spacing:2px;color:#a57c29}.qd-dialog h2{font-size:27px;line-height:1.3;margin:12px 40px 5px 0}.qd-name{font-size:14px;color:#727e6a;margin:0 0 24px}.qd-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}.qd-toolbar small{font-size:11px;color:#7b8671}.qd-toolbar button{display:flex;align-items:center;gap:7px;font-size:11px;white-space:nowrap}.qd-summary{display:flex;gap:14px;align-items:center;background:#f6f0df;padding:18px;border-radius:14px;color:#896b2c}.qd-summary.checks_passed{background:#eaf3ec;color:#2b7153}.qd-summary small{display:block;font-size:11px;margin-top:5px}.qd-summary strong{font-size:15px}.qd-checks{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:18px 0}.qd-checks article{display:flex;gap:10px;align-items:flex-start;border:1px solid #e8eadd;padding:14px;border-radius:12px;min-width:0}.qd-checks svg{flex-shrink:0;color:#ba9341}.qd-checks .ok svg{color:#398366}.qd-checks strong{font-size:12px;line-height:1.5;display:block}.qd-checks p{font-size:11px;line-height:1.65;color:#7b816f;margin:6px 0 0}.qd-section{border-top:1px solid #e7eadd;padding-top:20px;margin-top:20px}.qd-section h3{font-size:17px;margin:0 0 15px}.qd-section>summary{cursor:pointer;font-size:14px;font-weight:600;display:flex;align-items:center;gap:8px}.qd-agents,.qd-reason ul{list-style:none;padding:0;margin:14px 0}.qd-agents li,.qd-reason li{padding:10px 0;border-bottom:1px solid #edf0e6}.qd-agents strong,.qd-reason li strong{display:block;font-size:12px}.qd-agents span,.qd-reason li span{display:block;font-size:11px;color:#79846e;overflow-wrap:anywhere;margin-top:4px}.qd-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.qd-metrics>div{border-radius:12px;background:#f5f6ef;padding:16px}.qd-metrics strong{display:block;font-size:25px}.qd-metrics small{display:block;font-size:10px;line-height:1.5;color:#758068}.qd-note,.qd-scope{font-size:11px;line-height:1.7;color:#7c8574}.qd-scope{padding:16px;background:#f6f7f2;border-radius:12px;margin-top:22px}.qd-reason{border:1px solid #e6e8db;border-radius:12px;padding:13px;margin-top:10px}.qd-reason summary{display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:12px;cursor:pointer}.qd-reason summary span{line-height:1.6}.qd-reason b{padding:4px 8px;background:#f5edd9;border-radius:6px;color:#9a7730}.qd-error{background:#fff0ed;color:#a24d43;padding:14px;border-radius:12px;font-size:12px;line-height:1.7}@media(max-width:600px){.qd-overlay{padding:10px}.qd-dialog{padding:22px}.qd-checks{grid-template-columns:1fr}.qd-toolbar{align-items:flex-start;flex-direction:column}.qd-metrics{gap:6px}.qd-metrics>div{padding:11px}.qd-dialog h2{font-size:23px}}
</style>
